      "check_id": "CKV_AWS_273",
      "title": "AWS IAM user used instead of centralized SSO",
      "resource": "aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user",
      "severity": "MEDIUM",
      "explanation": "This resource creates a standalone AWS IAM user, which can enable long-lived identities outside centralized SSO lifecycle and access controls. The user is disabled from creation to ensure access is managed through SSO instead."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  count = 0\n\n  name = \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\"\n  path = \"/\"\n}\n",
  "fix_summary": "Disabled creation of the standalone IAM user while retaining the existing resource declaration, ensuring it cannot be provisioned instead of an SSO-managed identity."
}
